import 'package:flutter/material.dart';
import '../../core/api_client.dart';
import '../../core/format.dart';
class DashboardScreen extends StatefulWidget{const DashboardScreen({super.key});@override State<DashboardScreen> createState()=>_DashboardScreenState();}
class _DashboardScreenState extends State<DashboardScreen>{Map<String,dynamic> data={};bool loading=true;String? error;Future<void> load()async{setState(()=>loading=true);try{final v=await ApiClient.instance.get('/dashboard');if(mounted)setState(()=>data=Map<String,dynamic>.from(v as Map));}catch(e){if(mounted)setState(()=>error=ApiClient.instance.message(e));}finally{if(mounted)setState(()=>loading=false);}}@override void initState(){super.initState();load();}
Widget metric(String title,String value,IconData icon,{bool main=false})=>Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:main?const Color(0xFF4B4FE0):Colors.white,borderRadius:BorderRadius.circular(23),boxShadow:[BoxShadow(color:Colors.black.withValues(alpha:.035),blurRadius:18,offset:const Offset(0,7))]),child:Row(children:[Icon(icon,color:main?Colors.white:const Color(0xFF4B4FE0),size:25),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:TextStyle(color:main?Colors.white70:Colors.black54,fontSize:12)),const SizedBox(height:5),Text(value,style:TextStyle(color:main?Colors.white:Colors.black87,fontSize:20,fontWeight:FontWeight.w800))]))]));
@override Widget build(BuildContext context)=>RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.fromLTRB(20,16,20,100),children:[const Text('PAYDAY',style:TextStyle(color:Color(0xFF4B4FE0),fontWeight:FontWeight.w900,letterSpacing:2)),const SizedBox(height:5),const Text('Your overview',style:TextStyle(fontSize:28,fontWeight:FontWeight.w800,letterSpacing:-.8)),const SizedBox(height:20),if(loading)const LinearProgressIndicator(),if(error!=null)Text(error!),metric('Available balance',formatMoney(data['availableBalance'] as num?),Icons.account_balance_wallet_rounded,main:true),const SizedBox(height:12),Row(children:[Expanded(child:metric('Safe to spend',formatMoney(data['safeToSpendToday'] as num?),Icons.savings_outlined)),const SizedBox(width:10),Expanded(child:metric('Spent this cycle',formatMoney(data['spentThisCycle'] as num?),Icons.trending_down))]),const SizedBox(height:12),Row(children:[Expanded(child:metric('Salary received',formatMoney(data['salaryReceivedThisCycle'] as num?),Icons.payments_outlined)),const SizedBox(width:10),Expanded(child:metric('Saved this cycle',formatMoney(data['savedThisCycle'] as num?),Icons.flag_outlined))]),const SizedBox(height:24),const Text('Smart insights',style:TextStyle(fontSize:19,fontWeight:FontWeight.w800)),...(data['smartAlerts'] is List?(data['smartAlerts'] as List).take(5).map((a)=>Card(child:ListTile(leading:const Icon(Icons.auto_awesome,color:Color(0xFF4B4FE0)),title:Text(a['title']?.toString()??'Insight'),subtitle:Text(a['message']?.toString()??'')))):[]),const SizedBox(height:18),const Text('Recent activity',style:TextStyle(fontSize:19,fontWeight:FontWeight.w800)),...(data['recentTransactions'] is List?(data['recentTransactions'] as List).take(5).map((t)=>Card(child:ListTile(title:Text(t['category_name']?.toString()??t['note']?.toString()??'Transaction'),subtitle:Text(t['txn_date']?.toString()??''),trailing:Text(formatMoney(t['amount'] as num?))))):[])]));}
